const input = $input.first().json;
const body = input.body ?? input;

function findByKey(value, targetKey, seen = new Set()) {
  if (value === null || value === undefined) return undefined;
  if (typeof value !== 'object') return undefined;
  if (seen.has(value)) return undefined;
  seen.add(value);

  if (!Array.isArray(value) && Object.prototype.hasOwnProperty.call(value, targetKey)) {
    return value[targetKey];
  }

  const children = Array.isArray(value) ? value : Object.values(value);
  for (const child of children) {
    const found = findByKey(child, targetKey, seen);
    if (found !== undefined) return found;
  }

  return undefined;
}

function toText(value) {
  if (value === null || value === undefined) return '';

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return String(value).trim();
  }

  if (Array.isArray(value)) {
    return value.map(toText).filter(Boolean).join(' ').trim();
  }

  if (typeof value === 'object') {
    if (typeof value.plain_text === 'string') return value.plain_text.trim();
    if (typeof value.name === 'string') return value.name.trim();
    if (typeof value.content === 'string') return value.content.trim();

    for (const key of ['status', 'title', 'rich_text', 'select', 'value']) {
      if (value[key] !== undefined) {
        const text = toText(value[key]);
        if (text) return text;
      }
    }
  }

  return '';
}

const status = toText(findByKey(body, 'Статус'));
const issue = toText(findByKey(body, 'Обращение')) || 'Обращение';
const answer = toText(findByKey(body, 'Ответ'));
const chatId = toText(findByKey(body, 'Telegram chat ID'));

const statusText = {
  'В работе': `«${issue}» — заявка взята в работу.`,
  'Решено': `«${issue}» — заявка решена.`,
  'Не по адресу': `«${issue}» — обращение не по адресу.`,
}[status];

if (!statusText || !chatId) {
  return [];
}

const text = (status === 'Решено' || status === 'Не по адресу') && answer
  ? `${statusText}\n\n${answer}`
  : statusText;

return [{
  json: {
    chatId,
    text,
    status,
    issue,
    hasAnswer: Boolean(answer)
  }
}];
